/**
 * Ambient module declarations for non TypeScript assets.
 *
 * JSON imports resolve through the wildcard so route modules receive
 * `unknown` and must pass through loadBook/loadBuildMeta shape validation
 * before any field is read. The files under src/data/ are generated by
 * scripts/sync-payloads.js and are not committed, so no literal types can
 * be inferred from them at typecheck time.
 */
declare module "*.json" {
  const value: unknown;
  export default value;
}

declare module "*.css";

/**
 * Vite build time asset glob, declared here because tsconfig loads no
 * Vite client types (types is an empty list). The call is transformed
 * away at build time: the shipped bundle holds a plain URL string.
 */
interface ImportMeta {
  glob(
    pattern: string,
    options?: {
      readonly eager?: boolean;
      readonly query?: string;
      readonly import?: string;
    },
  ): Record<string, string>;
}
